<script setup lang="ts">
import WorkspaceNav from './WorkspaceNav.vue'
import AttendanceSummary from './AttendanceSummary.vue'
import StudentHomeworkList from './StudentHomeworkList.vue'
import MarkLegend from './MarkLegend.vue'
import EnglishDateInput from './EnglishDateInput.vue'
import {computed,onMounted,onUnmounted,reactive,ref} from 'vue'
import NoticeBoard from './NoticeBoard.vue'
import DailyMenu from './DailyMenu.vue'
import {scheduleApi,days} from '../schedules'
import {dismissAfterFourSeconds} from '../temporary-message'
defineProps<{loginId:string;busy:boolean;error:string}>();const emit=defineEmits<{logout:[]}>()
const profile=ref<any>(null),children=ref<any[]>([]),childId=ref(0),details=ref<any>(null),loading=ref(true),childLoading=ref(false),failure=ref(''),message=ref(''),saving=ref(false),page=ref('overview'),month=ref(''),notices=ref<any[]>([]),canteen=ref<any>(null)
const passwords=reactive({current:'',next:'',confirm:''}),contact=reactive({email:'',phone_number:''});dismissAfterFourSeconds(message)
const secondaryFailure=ref('')
const contactDirty=computed(()=>Boolean(profile.value&&(contact.email!==(profile.value.email??'')||contact.phone_number!==(profile.value.phone_number??''))))
function discardContact(){if(!contactDirty.value)return true;if(!window.confirm('Discard your unsaved contact changes?'))return false;contact.email=profile.value.email??'';contact.phone_number=profile.value.phone_number??'';return true}
function openPage(next:string){if(saving.value||!discardContact())return;page.value=next}
function logout(){if(discardContact())emit('logout')}
function beforeLeave(event:BeforeUnloadEvent){if(contactDirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeLeave))
onUnmounted(()=>{requestId++;parentRequest++;window.removeEventListener('beforeunload',beforeLeave)})
const tabs=[['overview','Overview'],['attendance','Attendance'],['homework','Homework'],['timetable','Timetable'],['notices','Notices'],['canteen','Canteen'],['account','My account']]
const statusLabel=(s:string)=>({present:'Present',absent:'Absent',late:'Late',excused:'Excused'}[s]??'Not marked')
const symbol=(s:string)=>({present:'O',absent:'X',late:'−',excused:'E'}[s]??'·')
const routines=computed(()=>{const groups=new Map<string,{days:string[];lessons:any[]}>();for(const day of [7,1,2,3,4,5,...((details.value?.timetable??[]).some((l:any)=>l.day_of_week===6)?[6]:[])]){const lessons=(details.value?.timetable??[]).filter((l:any)=>l.day_of_week===day);const key=JSON.stringify(lessons.map((l:any)=>[l.start_time,l.end_time,l.course_name,l.teacher_name,l.location]));if(groups.has(key))groups.get(key)!.days.push(days[day-1]);else groups.set(key,{days:[days[day-1]],lessons});}return [...groups.values()]})
let requestId=0,parentRequest=0
async function loadChild(){const ticket=++requestId;details.value=null;if(!childId.value)return;childLoading.value=true;failure.value='';try{const data=await scheduleApi('parent/children/'+childId.value+(month.value?'?month='+encodeURIComponent(month.value):''));if(ticket===requestId){details.value=data;month.value=data.attendance.month}}catch(e){if(ticket===requestId)failure.value=e instanceof Error?e.message:'Unable to load child records.'}finally{if(ticket===requestId)childLoading.value=false}}
async function load(){
 if(!discardContact())return
 const ticket=++parentRequest;loading.value=true;failure.value='';secondaryFailure.value='';details.value=null;profile.value=null;children.value=[];notices.value=[];canteen.value=null
 try{
  const me=await scheduleApi('parent/me');if(ticket!==parentRequest)return;profile.value=me.parent;contact.email=profile.value.email??'';contact.phone_number=profile.value.phone_number??''
  if(!profile.value.must_change_password){
   const data=await scheduleApi('parent/children');if(ticket!==parentRequest)return;children.value=data.children;month.value||=data.today.slice(0,7);if(!children.value.some(c=>c.id===childId.value))childId.value=children.value[0]?.id??0
   await loadChild();if(ticket!==parentRequest)return;loading.value=false
   const results=await Promise.allSettled([scheduleApi('parent/notices'),scheduleApi('parent/canteen')]);if(ticket!==parentRequest)return
   if(results[0].status==='fulfilled')notices.value=results[0].value.notices
   if(results[1].status==='fulfilled')canteen.value=results[1].value
   if(results.some(r=>r.status==='rejected'))secondaryFailure.value='Some notices or canteen information could not load. You can retry without changing school records.'
  }
 }catch(e){if(ticket===parentRequest)failure.value=e instanceof Error?e.message:'Unable to load parent dashboard.'}finally{if(ticket===parentRequest)loading.value=false}
}
async function changePassword(){if(saving.value)return;if(passwords.next!==passwords.confirm){failure.value='The new passwords do not match.';return;}saving.value=true;failure.value='';try{await scheduleApi('parent/password','POST',{current_password:passwords.current,new_password:passwords.next});passwords.current='';passwords.next='';passwords.confirm='';emit('logout')}catch(e){failure.value=e instanceof Error?e.message:'Unable to change password.'}finally{saving.value=false;passwords.current=''}}
async function saveContact(){saving.value=true;failure.value='';try{message.value=(await scheduleApi('parent/contact','PUT',contact)).message;Object.assign(profile.value,contact)}catch(e){failure.value=e instanceof Error?e.message:'Unable to save contact details.'}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="parent-shell" data-workspace="parent"><header class="parent-header"><div><p class="workspace-context">Parent workspace</p><h1>Your child’s school day</h1><p>{{profile?.full_name||loginId}}, {{loginId}}</p></div><button type="button" class="secondary" :disabled="busy||saving" @click="logout">Log out</button></header><main class="parent-main"><div v-if="error||failure" class="workspace-retry" role="alert"><p class="error">{{failure||error}}</p><button type="button" :disabled="loading||saving" @click="load">Try again</button></div><div v-if="secondaryFailure" class="workspace-inline-warning" role="status">{{secondaryFailure}} <button type="button" :disabled="loading||saving" @click="load">Refresh information</button></div><p v-if="message" class="success" role="status">{{message}}</p><p v-if="loading" role="status">Loading your parent account…</p>
<section v-else-if="profile?.must_change_password" class="card password-panel"><h2>Set your own password</h2><p>The school gave you an initial password. Change it before viewing your children’s records, then sign in again.</p><form @submit.prevent="changePassword"><fieldset :disabled="saving"><label>Initial / current password<input v-model="passwords.current" type="password" required maxlength="72" autocomplete="current-password"></label><label>New password<input v-model="passwords.next" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><label>Confirm new password<input v-model="passwords.confirm" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><p class="hint">At least 12 characters, maximum 72 UTF-8 bytes. Choose a different password from the initial one.</p><button>{{saving?'Updating…':'Change password and sign in again'}}</button></fieldset></form></section>
<template v-else-if="profile"><div class="child-toolbar"><label v-if="children.length>1">Your child<select v-model="childId" :disabled="childLoading" @change="loadChild"><option v-for="child in children" :key="child.id" :value="child.id">{{child.full_name}}, {{child.login_id}}</option></select></label><div v-else><h2>{{children[0]?.full_name||'No linked children yet'}}</h2><p v-if="children[0]" class="hint">Student ID {{children[0].login_id}}</p></div><label v-if="page==='attendance'">Month<EnglishDateInput v-model="month" type="month" min="2000-01" max="2200-12" :disabled="childLoading" @change="loadChild" /></label><button type="button" class="secondary" :disabled="loading||childLoading" @click="load">Refresh</button></div><p v-if="!children.length" class="empty-state">The school must verify and link your child. Contact the administrator; entering a student ID or scanning a QR cannot grant access.</p><WorkspaceNav :items="tabs.map(([id,label])=>({id:id!,label:label!}))" :current="page" label="Parent navigation" :disabled="saving" @select="openPage" /><p v-if="childLoading&&page!=='account'" role="status">Loading child records…</p>
<section v-if="page==='account'" class="card"><h2>My contact details</h2><p v-if="contactDirty" class="workspace-inline-warning" role="status">Unsaved contact changes</p><p class="hint">Only school administrators can link or unlink children. If your registered email is unavailable during a reset, contact the school directly.</p><form @submit.prevent="saveContact"><fieldset :disabled="saving"><div class="fields"><label>Email<input v-model="contact.email" type="email" maxlength="254" autocomplete="email"></label><label>Phone<input v-model="contact.phone_number" type="tel" maxlength="30" autocomplete="tel"></label></div><button>{{saving?'Saving…':'Save contact details'}}</button></fieldset></form><details class="password-details"><summary>Change my password</summary><form @submit.prevent="changePassword"><fieldset :disabled="saving"><label>Current password<input v-model="passwords.current" type="password" required maxlength="72" autocomplete="current-password"></label><label>New password<input v-model="passwords.next" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><label>Confirm new password<input v-model="passwords.confirm" type="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><button>Change password and sign in again</button></fieldset></form></details></section>
<section v-else-if="page==='notices'" class="card"><NoticeBoard reader="parent" /></section>
<section v-else-if="page==='canteen'" class="card"><p v-if="canteen?.info">{{canteen.info.name}}, {{canteen.info.location}}</p><DailyMenu reader="parent" /></section>
<template v-else-if="details&&!childLoading"><section v-if="page==='overview'" class="card"><h2>{{details.child.full_name}}</h2><p>{{details.current?'Grade '+details.current.grade_label+', Class '+details.current.class_name:'No current class assigned'}}</p><p class="hint">{{details.current?.academic_year}}</p><div class="overview-grid"><article><span>Today’s attendance</span><strong>{{symbol(details.attendance.today_status)}} {{statusLabel(details.attendance.today_status)}}</strong><small>{{details.today}}, Nepal time</small></article><article><span>Homeroom teacher</span><strong>{{details.homeroom||'Not confirmed'}}</strong></article><article><span>Usual classroom</span><strong>{{details.current?.room_number?'Room '+details.current.room_number:'Not assigned'}}</strong></article><article><span>Homework</span><strong>{{details.homework.length}} assignment(s)</strong><small>Open Homework for dates and instructions</small></article></div><p class="hint">These are school records for your linked child. Contact the school if something looks incorrect.</p></section>
<section v-else-if="page==='attendance'" class="card"><div class="section-heading"><div><h2>Monthly attendance</h2><MarkLegend kind="attendance" /></div></div><div class="register-scroll" tabindex="0" aria-label="Your child’s monthly attendance"><table class="register"><thead><tr><th scope="col">Student</th><th v-for="day in details.attendance.days" :key="day.date" scope="col">{{Number(day.date.slice(-2))}}</th></tr></thead><tbody><tr><th scope="row">{{details.child.full_name}}</th><td v-for="day in details.attendance.days" :key="day.date" :class="[day.status,{future:day.future}]" :title="day.date+': '+(day.future?'Future date':statusLabel(day.status))">{{day.future?'·':symbol(day.status)}}</td></tr></tbody></table></div><AttendanceSummary :totals="details.attendance.totals" /><div class="attendance-totals"><span>Present <strong>{{details.attendance.totals.present}}</strong></span><span>Absent <strong>{{details.attendance.totals.absent}}</strong></span><span>Late <strong>{{details.attendance.totals.late}}</strong></span><span>Excused <strong>{{details.attendance.totals.excused}}</strong></span><span>Adjusted absences <strong>{{details.attendance.totals.adjustedAbsences}}</strong></span></div><p class="hint">Every three late marks count as one additional absence within this month. Original marks remain unchanged; unmarked days are not counted as absences.</p></section>
<section v-else-if="page==='homework'" class="card"><h2>Homework</h2><p v-if="!details.homework.length" class="hint">No homework is currently shared for this child’s class.</p><StudentHomeworkList :items="details.homework" :today="details.today" /></section>
<section v-else-if="page==='timetable'" class="card"><h2>Weekly timetable</h2><p class="hint">Nepal time, matching school days are grouped together.</p><article v-for="group in routines" :key="group.days.join()" class="routine"><h3>{{group.days.join(', ')}}</h3><p v-if="!group.lessons.length" class="hint">No lessons recorded.</p><ul v-else><li v-for="lesson in group.lessons" :key="lesson.id"><time>{{lesson.start_time}} to {{lesson.end_time}}</time><div><strong>{{lesson.course_name}}</strong><small>{{lesson.teacher_name||'Teacher not assigned'}}, {{lesson.location||details.current?.room_number&&'Room '+details.current.room_number||'Room not specified'}}</small></div></li></ul></article><h3>Upcoming special rooms</h3><p v-if="!details.bookings.length" class="hint">No upcoming special-room bookings.</p><ul class="booking-list"><li v-for="b in details.bookings" :key="b.id">{{b.repeats_weekly?days[b.day_of_week-1]+', '+b.date+' to '+b.ends_on:b.date}}, {{b.start_time}} to {{b.end_time}}, {{b.room_number}} {{b.room_name}}, {{b.course_name}}</li></ul></section></template></template></main></div></template>
<style scoped>
