view-grid small{font-size:11px;color:var(--ui-legacy-64796c);margin-top:8px}.section-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.section-heading label{margin:0 0 16px}.register-scroll{overflow:auto;border:1px solid var(--ui-legacy-dce6df);border-radius:10px}.register{border-collapse:collapse;width:max-content;min-width:100%;font-size:13px}.register th,.register td{border:1px solid var(--ui-legacy-dce6df);min-width:34px;text-align:center;padding:12px 8px}.register th:first-child{min-width:140px;max-width:180px;white-space:normal;position:sticky;left:0;background:var(--ui-legacy-f5f8f5);text-align:left;overflow-wrap:anywhere}.register thead{background:var(--ui-legacy-f0f5f0)}.present{color:var(--ui-legacy-276d43)}.absent{color:var(--ui-legacy-a13d32);background:var(--ui-legacy-fff1ef)}.late{color:var(--ui-legacy-8b661c);background:var(--ui-legacy-fff6df)}.future{color:var(--ui-legacy-acb5af)}.attendance-totals{display:flex;gap:12px 16px;flex-wrap:wrap;margin:16px 0;font-size:13px}.attendance-totals strong{margin-left:8px}.notice{padding:16px 0;border-bottom:1px solid var(--ui-legacy-dce6df)}.notice:last-child{border:0}.preserve-lines{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px}.routine{padding:16px 0;border-bottom:1px solid var(--ui-legacy-dce6df)}.routine h3{line-height:1.5}.routine ul,.menu-list,.booking-list{list-style:none;padding:0}.routine li{display:flex;align-items:start;gap:16px;padding:12px 0;font-size:14px}.routine time{font-size:12px;white-space:nowrap;min-width:88px}.routine small,.menu-list small{display:block;font-size:12px;color:var(--ui-legacy-64796c);margin-top:4px}.booking-list{font-size:13px;line-height:1.7}.menu-list li{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid var(--ui-legacy-dce6df);font-size:14px}.password-details{border-top:1px solid var(--ui-legacy-dce6df);margin-top:24px;padding-top:16px}.password-details summary{cursor:pointer;min-height:44px}@media(max-width:600px){.parent-shell{padding:0 16px 24px}.parent-header{padding:16px 0}.parent-header h1{font-size:23px}.parent-shell .card{padding:16px}.fields,.overview-grid{grid-template-columns:1fr}.parent-tabs button{flex:1 1 100px}.routine li{gap:12px}.routine strong{font-size:13px}.parent-shell h2{font-size:19px}}
</style>
